import os
import logging
from multiprocessing import Lock
from taf.internal.managedobject import ManagedObject
from taf.trafficgenerator.iperf.exceptions import IperfLogPathError


mutex = Lock()


class IperfTrafficGenerator(ManagedObject):

    def __init__(self, host, iperf_cmds, log_path=None, logger=None):
        """
        Initial IperfTrafficGenerator instance.

        :param host: iperf host instance
        :type host: object
        :param iperf_cmds: iperf command instance
        :type iperf_cmds: object
        :param log_path: iperf traffic statistic log path
        :type log_path: str
        """
        super(IperfTrafficGenerator, self).__init__()
        self._host = host
        self._iperf_cmds = iperf_cmds
        self._log_path = log_path
        self._logger = logger or logging
        self.add_prerequisite(self._host)
        self._executable_resources = None  # resources of the process generated from remote/local

    @property
    def log_path(self):
        return self._log_path

    def _teardown(self):
        pass

    def force_port_available(self):
        self._iperf_cmds.force_port_available()

    def start(self):
        """
        Start traffic with iperf command.

        :return: None
        """
        self._executable_resources = self._iperf_cmds.start_iperf()
        self._logger.info('{} iperf process started: {}'.format(self._host, self._executable_resources.pid))

    def stop(self, timeout, force):
        """
        Stop already running traffic with command.

        No action if traffic is already finished.

        :param timeout: timeout waiting for iperf quit
        :param force: force to kill iperf process, False by default
        :return: None
        """
        try:
            if self.is_running():
                self._logger.info('{} iperf process stopping: {}'.format(self._host, self._executable_resources.pid))
                self._iperf_cmds.stop_iperf(self._executable_resources, timeout, force)
            self._executable_resources = None
        finally:
            self._fetch_file()
            self._host.remove_file(self._iperf_cmds.temp_log_path)

    def is_running(self):
        """
        Check if traffic is running

        :return: boolean
        """
        return self._iperf_cmds.check_iperf_alive(self._executable_resources.pid)

    def get_output(self):
        """
        Get traffic output

        :return: str with raw output
        """
        return self._host.get_output(self._iperf_cmds.temp_log_path)

    def _fetch_file(self):
        if self._log_path is None:
            return

        if os.path.isdir(self._log_path):
            raise IperfLogPathError('"{}" should be file path rather than folder.'.format(self._log_path))

        log_dir = os.path.dirname(self._log_path)
        if log_dir:
            self._mkdir(log_dir)
        self._remove_local_existing_file(self._log_path)
        self._host.fetch_file(self._iperf_cmds.temp_log_path, self._log_path)

    def _mkdir(self, dir_path):
        if not os.path.exists(dir_path):
            self._logger.warning('"{}" is not exist, will be created.'.format(dir_path))
            os.makedirs(dir_path)

            if not os.path.exists(dir_path):
                raise IperfLogPathError('create folder "{}" failed, please check the folder if it is illegal.'.format(dir_path))
            self._logger.info('create folder "{}" successfully.'.format(dir_path))

    def _remove_local_existing_file(self, file_path):
        if os.path.exists(file_path) and os.path.isfile(file_path):
            self._logger.warning('file "{}" is exist, will be removed for recreation.'.format(file_path))
            try:
                os.remove(file_path)
            except Exception as e:
                self._logger.warning("failed to remove local file {} for {}".format(file_path, e))
                return

            if os.path.exists(file_path) and os.path.isfile(file_path):
                raise IperfLogPathError('failed to remove file "{}".'.format(file_path))


class IperfServerTrafficGenerator(IperfTrafficGenerator):
    pass


class IperfClientTrafficGenerator(IperfTrafficGenerator):
    pass
